------------ import ------------
local CDTimerModule = CS.Engine.Modules.CDTimerModule
local KTool = CS.Engine.Lib.KTool
local KCookie = CS.Engine.Lib.KCookie
------------ import ------------

------------ define ------------
local CountDownTime = 2592000 --30 * 86400 30天的秒数
------------ define ------------

--- from: Assets/BundleResources/Prefabs/PassportDialog.prefab > name: PreDownloadCountDown
---@class PreDownloadText
---@field Env                           	PreDownloadText                         
---@field controller                    	Engine.Modules.LuaBehaviour             
---@field TxtTips                       	UnityEngine.RectTransform               	@ 0    
---@field TxtNum                        	UnityEngine.RectTransform               	@ 1    
local PreDownloadText = Class('PreDownloadText')

function PreDownloadText:__init()
    self.isStarting = false
end

function PreDownloadText:__delete()
    self.isStarting = false
end

function PreDownloadText:GetTime(second)
    local  h, m, s
    h = math.floor(second / 3600)
    m = math.floor((second - 3600 * h) / 60)
    s = math.floor(second - 3600 * h - 60 * m)
    --h = h < 10 and "0" .. h or h
    --m = m < 10 and "0" .. m or m
    --s = s < 10 and "0" .. s or s
    local hStr = h > 0 and string.format_color_tag(string.format('%02d', h), '#00FFFF') or string.format_color_tag(string.format('%02d', h), '#FFFFFF')
    local mStr = (h > 0 or m > 0) and string.format_color_tag(string.format('%02d', m), '#00FFFF') or string.format_color_tag(string.format('%02d', m), '#FFFFFF')
    local sStr = (h > 0 or m > 0 or s > 0) and string.format_color_tag(string.format('%02d', s), '#00FFFF') or string.format_color_tag(string.format('%02d', s), '#FFFFFF')
    return hStr .. ":" .. mStr .. ":" .. sStr
end

function PreDownloadText:Awake()
    self:CloseTimer()
    local isRunning = KCookie.Get("IS_RUNNING")
    if string.isEmpty(isRunning) then
        KCookie.Set("IS_RUNNING", '1')
        self.timerDownloader = CDTimerModule.GetInstance():AddCD(1, function(count, id, countElapsed)
            if self.isStarting then
                ---@type UserComponent
                local userComponent = GameUtils.GetEntityCompByType(ECSComponentType.Constants.UserComponent)
                if userComponent then
                    local remainTime = checkNumber(userComponent.userInfo.isPrePlayOpened)
                    userComponent.userInfo.isPrePlayOpened = remainTime - countElapsed
                    if userComponent.userInfo.isPrePlayOpened <= 0 then
                        self.isStarting = false
                        ---发送一个消息事件，开服的逻辑
                        Events.Broadcast(Constants.EventNames.UIGameInitEvent)
                    else
                        CfUtils.FillText(self.TxtNum, self:GetTime(userComponent.userInfo.isPrePlayOpened))
                    end
                end
            end
        end, CountDownTime, false, true)
    else
       CfUtils.SetActive(self.controller, false)
    end
end

function PreDownloadText:CloseTimer()
    if isNotNull(self.timerDownloader) then
        CDTimerModule.GetInstance():RemoveCD(self.timerDownloader)
        self.timerDownloader = nil
    end
end

local function GetClientTimezone()
    local nowTime  = os.time(os.date("*t"))
    local pureTime = os.time(os.date("!*t", nowTime))
    if os.date("*t", os.time()).isdst then
        nowTime = nowTime + 3600
    end
    return os.difftime(nowTime, pureTime)
end

local function l10nTimeData(timeFormat, timestamp)
    local format = tostring(timeFormat or '!%Y-%m-%d %H:%M:%S')
    return os.date(format, timestamp + 0 - GetClientTimezone())
end

function PreDownloadText:OnEnable()
    ---@type UserComponent
    local userComponent = GameUtils.GetEntityCompByType(ECSComponentType.Constants.UserComponent)
    if userComponent then
        if KTool.UNITY_EDITOR() then
            --userComponent.userInfo.isPrePlayOpened = 1
        end
        CfUtils.FillText(self.TxtNum, self:GetTime(userComponent.userInfo.isPrePlayOpened))
        self.isStarting = true
        if GameUtils.isZmFunction() then
            --local str = os.date(localize("%Y年%m月%d日%H时%M分"), userComponent.userInfo.prePlayerTimestamp)
            local str = l10nTimeData(localize("%Y年%m月%d日%H时%M分"), userComponent.userInfo.prePlayerTimestamp) .. ' (UTC+0)'
            CfUtils.FillText(self.TxtTips, localize('游戏将于_time_正式开服', {_time_ = str}))
        else
            local str = os.date(localize("%Y年%m月%d日%H时%M分"), userComponent.userInfo.prePlayerTimestamp)
            CfUtils.FillText(self.TxtTips, localize('游戏将于_time_正式开服', {_time_ = str}))
        end
    end
end

function PreDownloadText:OnDestroy()
    self.isStarting = false
    self:CloseTimer()
    self.controller = nil--luabehaviour 中CSharp对象
    self:Delete()
    self = nil
end

return PreDownloadText